// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import {
    createCollection,
    createLink,
    createHighlight,
    getHighlightsList,
    deleteHighlight,
    deleteLink,
    deleteCollection
} from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // Declaration of variables
    const take = "1";

    const collectionsPostResponse = await createCollection(
        client, headers, "Highlights scenario collection"
    );

    // Generated Assertions
    expect(collectionsPostResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsPostResponse, "response.name"), 'name').toBe("Highlights scenario collection");
    expect(getResponseValue(collectionsPostResponse, "response.color"), 'color').toBe("#0ea5e9");
    expect(getResponseValue(collectionsPostResponse, "response.isPublic"), 'isPublic').toBe(false);
    expect(getResponseValue(collectionsPostResponse, "response.id"), 'id').toBeGreaterThan(0);

    const linksPostResponse = await createLink(
        client,
        headers,
        getResponseValue(collectionsPostResponse, "response.id"),
        getResponseValue(collectionsPostResponse, "response.ownerId"),
        "Highlights scenario article",
        "https://example.com/highlights-scenario-article"
    );

    // Generated Assertions
    expect(linksPostResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(linksPostResponse, "response.name"), 'name').toBe("Highlights scenario article");
    expect(getResponseValue(linksPostResponse, "response.url"), 'url').toBe("https://example.com/highlights-scenario-article");
    expect(getResponseValue(linksPostResponse, "response.type"), 'type').toBe("url");
    expect(getResponseValue(linksPostResponse, "response.collectionId"), 'collectionId').toBe(getResponseValue(collectionsPostResponse, "response.id"));
    expect(getResponseValue(linksPostResponse, "response.id"), 'id').toBeGreaterThan(0);

    const highlightsPostResponse = await createHighlight(
        client,
        headers,
        getResponseValue(linksPostResponse, "response.id"),
        "yellow",
        "A yellow passage worth keeping",
        "a plain note",
        0,
        20
    );

    // Generated Assertions
    expect(highlightsPostResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(highlightsPostResponse, "response.color"), 'color').toBe("yellow");
    expect(getResponseValue(highlightsPostResponse, "response.text"), 'text').toBe("A yellow passage worth keeping");
    expect(getResponseValue(highlightsPostResponse, "response.comment"), 'comment').toBe("a plain note");
    expect(getResponseValue(highlightsPostResponse, "response.startOffset"), 'startOffset').toBe(0);
    expect(getResponseValue(highlightsPostResponse, "response.endOffset"), 'endOffset').toBe(20);
    expect(getResponseValue(highlightsPostResponse, "response.linkId"), 'linkId').toBe(getResponseValue(linksPostResponse, "response.id"));
    expect(getResponseValue(highlightsPostResponse, "response.id"), 'id').toBeGreaterThan(0);
    expect(getResponseValue(highlightsPostResponse, "response.createdAt"), 'createdAt').toMatch(/^\d{4}-\d{2}-\d{2}T/);

    const highlightsPost1Response = await createHighlight(
        client,
        headers,
        getResponseValue(linksPostResponse, "response.id"),
        "green",
        "A green passage worth keeping",
        "note token skyzz1 lives only here",
        40,
        60
    );

    // Generated Assertions
    expect(highlightsPost1Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(highlightsPost1Response, "response.color"), 'color').toBe("green");
    expect(getResponseValue(highlightsPost1Response, "response.text"), 'text').toBe("A green passage worth keeping");
    expect(getResponseValue(highlightsPost1Response, "response.comment"), 'comment').toBe("note token skyzz1 lives only here");
    expect(getResponseValue(highlightsPost1Response, "response.startOffset"), 'startOffset').toBe(40);
    expect(getResponseValue(highlightsPost1Response, "response.endOffset"), 'endOffset').toBe(60);
    expect(getResponseValue(highlightsPost1Response, "response.linkId"), 'linkId').toBe(getResponseValue(linksPostResponse, "response.id"));

    const highlightsGetResponse = await getHighlightsList(client, headers);

    // Generated Assertions
    // Newest first (id desc): the green highlight was created last, the yellow one before it.
    expect(highlightsGetResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(highlightsGetResponse, "response.highlights.0.id"), 'newest highlight id').toBe(getResponseValue(highlightsPost1Response, "response.id"));
    expect(getResponseValue(highlightsGetResponse, "response.highlights.0.color"), 'newest highlight color').toBe("green");
    expect(getResponseValue(highlightsGetResponse, "response.highlights.0.comment"), 'newest highlight comment').toBe("note token skyzz1 lives only here");
    expect(getResponseValue(highlightsGetResponse, "response.highlights.0.link.id"), 'source link id').toBe(getResponseValue(linksPostResponse, "response.id"));
    expect(getResponseValue(highlightsGetResponse, "response.highlights.0.link.name"), 'source link name').toBe("Highlights scenario article");
    expect(getResponseValue(highlightsGetResponse, "response.highlights.0.link.url"), 'source link url').toBe("https://example.com/highlights-scenario-article");
    expect(getResponseValue(highlightsGetResponse, "response.highlights.1.id"), 'second newest highlight id').toBe(getResponseValue(highlightsPostResponse, "response.id"));
    expect(getResponseValue(highlightsGetResponse, "response.highlights.1.color"), 'second newest highlight color').toBe("yellow");
    expect(getResponseValue(highlightsGetResponse, "response.highlights.1.link.id"), 'second source link id').toBe(getResponseValue(linksPostResponse, "response.id"));

    const highlightsGet1Response = await getHighlightsList(
        client, headers, {"take": [take]}
    );

    // Generated Assertions
    // take=1 returns exactly one row and a cursor pointing at it.
    expect(highlightsGet1Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(highlightsGet1Response, "response.highlights").length, 'page size').toBe(1);
    expect(getResponseValue(highlightsGet1Response, "response.highlights.0.id"), 'first page row').toBe(getResponseValue(highlightsPost1Response, "response.id"));
    expect(getResponseValue(highlightsGet1Response, "response.highlights.1"), 'no second row on a take=1 page').toBeNull();
    expect(getResponseValue(highlightsGet1Response, "response.nextCursor"), 'nextCursor').toBe(getResponseValue(highlightsPost1Response, "response.id"));

    const highlightsGet2Response = await getHighlightsList(
        client,
        headers,
        {
            "cursor": [getResponseValue(highlightsGet1Response, "response.nextCursor")],
            "take": [take]
        }
    );

    // Generated Assertions
    // The cursor page never repeats the row the cursor named.
    expect(highlightsGet2Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(highlightsGet2Response, "response.highlights").length, 'page size').toBe(1);
    expect(getResponseValue(highlightsGet2Response, "response.highlights.0.id"), 'second page row').toBe(getResponseValue(highlightsPostResponse, "response.id"));
    expect(getResponseValue(highlightsGet2Response, "response.highlights.0.id"), 'second page does not repeat the first').not.toBe(getResponseValue(highlightsGet1Response, "response.highlights.0.id"));
    expect(getResponseValue(highlightsGet2Response, "response.highlights.1"), 'no second row on a take=1 page').toBeNull();

    const highlightsGet3Response = await getHighlightsList(
        client, headers, {"color": ["yellow"]}
    );

    // Generated Assertions
    // The green highlight is newer, so it would head an unfiltered list; the yellow one heading
    // this list is what proves the colour filter excluded it.
    expect(highlightsGet3Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(highlightsGet3Response, "response.highlights.0.id"), 'newest yellow highlight').toBe(getResponseValue(highlightsPostResponse, "response.id"));
    expect(getResponseValue(highlightsGet3Response, "response.highlights.0.color"), 'colour of the filtered row').toBe("yellow");
    expect(getResponseValue(highlightsGet3Response, "response.highlights.0.id"), 'the green highlight is filtered out').not.toBe(getResponseValue(highlightsPost1Response, "response.id"));

    const highlightsGet4Response = await getHighlightsList(
        client, headers, {"q": ["skyzz1"]}
    );

    // Generated Assertions
    // skyzz1 appears only in the green highlight's NOTE, never in any highlight text.
    expect(highlightsGet4Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(highlightsGet4Response, "response.highlights").length, 'note search result count').toBe(1);
    expect(getResponseValue(highlightsGet4Response, "response.highlights.0.id"), 'note search match').toBe(getResponseValue(highlightsPost1Response, "response.id"));
    expect(getResponseValue(highlightsGet4Response, "response.highlights.0.comment"), 'matched note').toBe("note token skyzz1 lives only here");
    expect(getResponseValue(highlightsGet4Response, "response.highlights.0.text"), 'matched highlight text does not carry the token').toBe("A green passage worth keeping");
    expect(getResponseValue(highlightsGet4Response, "response.highlights.1"), 'no second note-search match').toBeNull();
    expect(getResponseValue(highlightsGet4Response, "response.nextCursor"), 'nextCursor on the last page').toBeNull();

    const highlightsHighlightsDeleteResponse = await deleteHighlight(
        client, headers, getResponseValue(highlightsPostResponse, "response.id")
    );

    // Generated Assertions
    expect(highlightsHighlightsDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(highlightsHighlightsDeleteResponse, "response"), 'deleted highlight id').toBe(getResponseValue(highlightsPostResponse, "response.id"));

    const highlightsHighlightsDelete1Response = await deleteHighlight(
        client, headers, getResponseValue(highlightsPost1Response, "response.id")
    );

    // Generated Assertions
    expect(highlightsHighlightsDelete1Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(highlightsHighlightsDelete1Response, "response"), 'deleted highlight id').toBe(getResponseValue(highlightsPost1Response, "response.id"));

    const linksLinksDeleteResponse = await deleteLink(
        client, headers, getResponseValue(linksPostResponse, "response.id")
    );

    // Generated Assertions
    expect(linksLinksDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(linksLinksDeleteResponse, "response.id"), 'deleted link id').toBe(getResponseValue(linksPostResponse, "response.id"));

    const collectionsCollectionsDeleteResponse = await deleteCollection(
        client, headers, getResponseValue(collectionsPostResponse, "response.id")
    );

    // Generated Assertions
    expect(collectionsCollectionsDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsCollectionsDeleteResponse, "response.id"), 'deleted collection id').toBe(getResponseValue(collectionsPostResponse, "response.id"));
});
